from pathlib import Path
import xml.etree.ElementTree as ET

ROOT = Path("the_current_flutter")
ANDROID = ROOT / "android" / "app" / "src" / "main"
RES = ANDROID / "res"

# Use Android's native launch window for a fast, reliable splash before Flutter starts.
# The NF artwork is generated by app_branding.py in the same build.
for values_dir in (RES / "values", RES / "values-night"):
    styles = values_dir / "styles.xml"
    if not styles.exists():
        continue
    text = styles.read_text(encoding="utf-8")
    # Flutter's LaunchTheme uses launch_background as its window background.
    # Keep the standard theme structure; launch_background is updated below.
    if "LaunchTheme" in text and "windowBackground" not in text:
        text = text.replace(
            '<style name="LaunchTheme" parent="',
            '<style name="LaunchTheme" parent="',
            1,
        )
    styles.write_text(text, encoding="utf-8")

# Native Android launch drawable. The logo is centered over a clean white background.
drawable = RES / "drawable"
drawable.mkdir(parents=True, exist_ok=True)
(drawable / "launch_background.xml").write_text("""<?xml version="1.0" encoding="utf-8"?>
<layer-list xmlns:android="http://schemas.android.com/apk/res/android">
    <item android:drawable="@android:color/white" />
    <item>
        <bitmap
            android:gravity="center"
            android:src="@mipmap/ic_launcher" />
    </item>
</layer-list>
""", encoding="utf-8")

# Android 12+ splash-screen API attributes, where supported by the installed SDK.
values = RES / "values"
values.mkdir(parents=True, exist_ok=True)
styles = values / "styles.xml"
if styles.exists():
    text = styles.read_text(encoding="utf-8")
    if "windowSplashScreenBackground" not in text:
        import re
        match = re.search(r'<style name="LaunchTheme"[^>]*>', text)
        if match:
            insert = """\n        <item name="android:windowSplashScreenBackground">#FFFFFF</item>
        <item name="android:windowSplashScreenAnimatedIcon">@mipmap/ic_launcher</item>"""
            text = text[:match.end()] + insert + text[match.end():]
            styles.write_text(text, encoding="utf-8")

print("Configured native Android splash screen with centered News Feed launcher mark.")
